mapper.select:
SELECT COUNT(*)
FROM TB_ITEM_CHECKLIST
WHERE ITEM_ID = #{itemId}

mapper.update:
UPDATE TB_ITEM_CHECKLIST
SET SORT_ORDER = #{sortOrder},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE CHECKLIST_ID = #{checklistId}

update.foreach:
UPDATE TB_ITEM_CHECKLIST
SET SORT_ORDER = #{index},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{updatedBy}
WHERE CHECKLIST_ID = #{checklistId}

mapper.select:
SELECT COALESCE(MAX(SORT_ORDER), 0) + 1
FROM TB_ITEM_CHECKLIST
WHERE ITEM_ID = #{itemId}
